// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {

        address admin = address(this);

        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        bool ok;
        try c.setOwner(caller) { ok = true; } catch { ok = false; }
        assertTrue(ok);
        assertTrue(c.owner() == caller);

        vm.assume(caller != admin);

        vm.prank(caller);
        bool ok2;
        try c.setOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!ok2 || c.owner() == caller);
    }
}
